type FixedProductMarketMakersClockKey struct {
	ID common.Address
}

func NewFixedProductMarketMakersClockKey(value MemoryFixedProductMarketMaker) FixedProductMarketMakersClockKey {
	return FixedProductMarketMakersClockKey{ID: value.ID}
}

type FixedProductMarketMakersClockEntry struct {
	key        FixedProductMarketMakersClockKey
	value      MemoryFixedProductMarketMaker
	referenced uint32
	inUse      uint32
}

type FixedProductMarketMakersClockCache struct {
	// buckets, next, ring form a fixed-size clock replacement cache.
	// SINGLE-OWNER CONTRACT: This cache is NOT thread-safe. All operations
	// must occur from a single goroutine (the processor). Concurrent access
	// will corrupt the linked-list structures and cause data races.
	// The atomics used for entry flags (inUse, referenced) protect only
	// the per-slot state, NOT the cache index structures.
	buckets  []int32
	next     []int32
	ring     []FixedProductMarketMakersClockEntry
	mask     uint32
	capacity uint64
	hand     uint64
	size     uint64
	// cold is an optional Pebble-backed tier holding evicted entries (raw bytes for
	// pointer-free entities, or a marshaled payload for serializable ones). nil
	// unless attached via HotState.EnableColdCache.
	cold    *coldcache.Store
	metrics *BatchResolverMetrics
}

func NewFixedProductMarketMakersClockCache(capacity uint64) *FixedProductMarketMakersClockCache {
	if capacity == 0 {
		capacity = DefaultClockCacheCapacity
	}
	bucketCount := uint64(8)
	for bucketCount < capacity*2 {
		bucketCount <<= 1
	}
	c := &FixedProductMarketMakersClockCache{
		ring:     make([]FixedProductMarketMakersClockEntry, capacity),
		buckets:  make([]int32, bucketCount),
		next:     make([]int32, capacity),
		mask:     uint32(bucketCount - 1),
		capacity: capacity,
	}
	for i := range c.buckets {
		c.buckets[i] = -1
	}
	for i := range c.next {
		c.next[i] = -1
	}
	return c
}

func (c *FixedProductMarketMakersClockCache) keyHash(key FixedProductMarketMakersClockKey) uint32 {
	h := uint64(1469598103934665603)
	h = clockHash20(h, key.ID[:])
	return uint32(h^(h>>32)) & c.mask
}

func (c *FixedProductMarketMakersClockCache) idxLookup(key FixedProductMarketMakersClockKey) (uint64, bool) {
	for i := c.buckets[c.keyHash(key)]; i >= 0; i = c.next[i] {
		if c.ring[i].key == key {
			return uint64(i), true
		}
	}
	return 0, false
}

func (c *FixedProductMarketMakersClockCache) idxInsert(key FixedProductMarketMakersClockKey, ringIdx uint32) {
	h := c.keyHash(key)
	c.next[ringIdx] = c.buckets[h]
	c.buckets[h] = int32(ringIdx)
}

func (c *FixedProductMarketMakersClockCache) idxUnlink(key FixedProductMarketMakersClockKey) {
	h := c.keyHash(key)
	prev := int32(-1)
	for i := c.buckets[h]; i >= 0; i = c.next[i] {
		if c.ring[i].key == key {
			if prev < 0 {
				c.buckets[h] = c.next[i]
			} else {
				c.next[prev] = c.next[i]
			}
			c.next[i] = -1
			return
		}
		prev = i
	}
}

func (c *FixedProductMarketMakersClockCache) Set(value MemoryFixedProductMarketMaker) {
	c.SetByKey(NewFixedProductMarketMakersClockKey(value), value)
}

func (c *FixedProductMarketMakersClockCache) SetByKey(key FixedProductMarketMakersClockKey, value MemoryFixedProductMarketMaker) {
	if idx, ok := c.idxLookup(key); ok {
		e := &c.ring[idx]
		if atomic.LoadUint32(&e.inUse) == 1 && e.key == key {
			e.value = value
			atomic.StoreUint32(&e.referenced, 1)
			return
		}
	}
	for {
		hand := atomic.AddUint64(&c.hand, 1)
		idx := (hand - 1) % c.capacity
		e := &c.ring[idx]
		if atomic.CompareAndSwapUint32(&e.inUse, 1, 0) {
			if atomic.LoadUint32(&e.referenced) == 1 {
				atomic.StoreUint32(&e.referenced, 0)
				atomic.StoreUint32(&e.inUse, 1)
				continue
			}
			if c.cold != nil {
				c.cold.Put(unsafe.Slice((*byte)(unsafe.Pointer(&e.key)), unsafe.Sizeof(e.key)), unsafe.Slice((*byte)(unsafe.Pointer(&e.value)), unsafe.Sizeof(e.value)))
			}
			c.idxUnlink(e.key)
			e.key = key
			e.value = value
			atomic.StoreUint32(&e.referenced, 0)
			c.idxInsert(key, uint32(idx))
			atomic.StoreUint32(&e.inUse, 1)
			return
		}
		if atomic.LoadUint32(&e.inUse) == 0 {
			if atomic.CompareAndSwapUint32(&e.inUse, 0, 2) {
				e.key = key
				e.value = value
				atomic.StoreUint32(&e.referenced, 0)
				c.idxInsert(key, uint32(idx))
				atomic.AddUint64(&c.size, 1)
				atomic.StoreUint32(&e.inUse, 1)
				return
			}
		}
	}
}

func (c *FixedProductMarketMakersClockCache) Get(key FixedProductMarketMakersClockKey) (MemoryFixedProductMarketMaker, bool) {
	if idx, ok := c.idxLookup(key); ok {
		e := &c.ring[idx]
		if atomic.LoadUint32(&e.inUse) == 1 && e.key == key {
			atomic.StoreUint32(&e.referenced, 1)
			if c.metrics != nil {
				c.metrics.HotHits++
			}
			return e.value, true
		}
	}
	if c.cold != nil {
		// GetInto copies the stored bytes straight into v (a fixed-size value
		// whose layout matches the bytes written on eviction), avoiding the
		// per-hit []byte allocation that the value-returning cold.Get does. key is
		// copied to a local first: taking &key directly forces the key parameter
		// to the heap on EVERY Get (escape analysis is flow-insensitive), including
		// hot hits that never reach this cold branch. &k keeps the escape contained.
		k := key
		var v MemoryFixedProductMarketMaker
		if found, _ := c.cold.GetInto(unsafe.Slice((*byte)(unsafe.Pointer(&v)), unsafe.Sizeof(v)), unsafe.Slice((*byte)(unsafe.Pointer(&k)), unsafe.Sizeof(k))); found {
			c.SetByKey(key, v)
			if c.metrics != nil {
				c.metrics.ColdHits++
			}
			return v, true
		}
	}
	return MemoryFixedProductMarketMaker{}, false
}

func (c *FixedProductMarketMakersClockCache) GetByFields(id common.Address) (MemoryFixedProductMarketMaker, bool) {
	return c.Get(FixedProductMarketMakersClockKey{ID: id})
}

func (c *FixedProductMarketMakersClockCache) ColdMightContain(id common.Address) bool {
	if c == nil || c.cold == nil {
		return false
	}
	k := FixedProductMarketMakersClockKey{ID: id}
	return c.cold.MightContain(unsafe.Slice((*byte)(unsafe.Pointer(&k)), unsafe.Sizeof(k)))
}

func (c *FixedProductMarketMakersClockCache) Delete(key FixedProductMarketMakersClockKey) bool {
	idx, ok := c.idxLookup(key)
	if !ok {
		return false
	}
	e := &c.ring[idx]
	if atomic.CompareAndSwapUint32(&e.inUse, 1, 0) {
		if e.key == key {
			c.idxUnlink(key)
			if c.cold != nil {
				c.cold.Delete(unsafe.Slice((*byte)(unsafe.Pointer(&key)), unsafe.Sizeof(key)))
			}
			e.key = FixedProductMarketMakersClockKey{}
			e.value = MemoryFixedProductMarketMaker{}
			atomic.StoreUint32(&e.referenced, 0)
			atomic.AddUint64(&c.size, ^uint64(0))
			return true
		}
		atomic.StoreUint32(&e.inUse, 1)
	}
	return false
}

func (c *FixedProductMarketMakersClockCache) Range(fn func(FixedProductMarketMakersClockKey, MemoryFixedProductMarketMaker) bool) {
	if fn == nil {
		return
	}
	limit := atomic.LoadUint64(&c.hand)
	if limit > c.capacity {
		limit = c.capacity
	}
	for i := uint64(0); i < limit; i++ {
		e := &c.ring[i]
		if atomic.LoadUint32(&e.inUse) == 1 {
			if !fn(e.key, e.value) {
				return
			}
		}
	}
}

func (c *FixedProductMarketMakersClockCache) AppendValues(dst []MemoryFixedProductMarketMaker) []MemoryFixedProductMarketMaker {
	if c == nil {
		return dst
	}
	if atomic.LoadUint64(&c.size) == 0 {
		return dst
	}
	limit := atomic.LoadUint64(&c.hand)
	if limit > c.capacity {
		limit = c.capacity
	}
	for i := 0; i < int(limit); i++ {
		e := &c.ring[i]
		if atomic.LoadUint32(&e.inUse) == 1 {
			dst = append(dst, e.value)
		}
	}
	return dst
}

func (c *FixedProductMarketMakersClockCache) Len() uint64 {
	return atomic.LoadUint64(&c.size)
}

