func (s *HotState) ResolveAllPending(ctx context.Context, conn *ch.Client, db string) error {
	if s == nil || conn == nil {
		return nil
	}
	if err := s.ConditionsResolver.Resolve(ctx, conn, db); err != nil {
		return err
	}
	if err := s.UserPositionsResolver.Resolve(ctx, conn, db); err != nil {
		return err
	}
	if err := s.MarketsResolver.Resolve(ctx, conn, db); err != nil {
		return err
	}
	if err := s.NegRiskEventsResolver.Resolve(ctx, conn, db); err != nil {
		return err
	}
	if err := s.FixedProductMarketMakersResolver.Resolve(ctx, conn, db); err != nil {
		return err
	}
	return nil
}

func asyncResolveEnabled() bool {
	if v := os.Getenv("SQD_ASYNC_RESOLVE"); v != "" {
		return v == "1" || v == "true" || v == "yes"
	}
	return false
}

func asyncResolveConcurrency() int {
	if v := os.Getenv("SQD_ASYNC_RESOLVE_CONCURRENCY"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			return n
		}
	}
	return 4
}

type resolveResult struct {
	err error
}

func (s *HotState) StartResolveAllPending(ctx context.Context, conn *ch.Client, db string) bool {
	if s == nil || conn == nil || !s.resolveAsyncEnabled {
		return false
	}
	if s == nil || s.resolveInProgress {
		return false
	}
	hasPending := false
	if s.ConditionsResolver.Pending() > 0 {
		hasPending = true
	}
	if s.UserPositionsResolver.Pending() > 0 {
		hasPending = true
	}
	if s.MarketsResolver.Pending() > 0 {
		hasPending = true
	}
	if s.NegRiskEventsResolver.Pending() > 0 {
		hasPending = true
	}
	if s.FixedProductMarketMakersResolver.Pending() > 0 {
		hasPending = true
	}
	if !hasPending {
		return false
	}
	s.mu.Lock()
	s.resolveInProgress = true
	s.resolveConn = conn
	s.resolveDB = db
	s.resolveCtx, s.resolveCancel = context.WithCancel(ctx)
	s.mu.Unlock()
	if s.resolveDone == nil {
		s.resolveDone = make(chan resolveResult, 1)
	}
	go func() {
		defer func() {
			if r := recover(); r != nil {
				s.resolveDone <- resolveResult{err: fmt.Errorf("resolve panic: %v", r)}
			}
		}()
		err := s.resolveAllParallel(s.resolveCtx, conn, db)
		s.resolveDone <- resolveResult{err: err}
	}()
	return true
}

func (s *HotState) PollResolveAllPending() error {
	if s == nil || s.resolveDone == nil {
		return nil
	}
	select {
	case result := <-s.resolveDone:
		s.resolveInProgress = false
		s.resolveDone = nil
		if s.resolveCancel != nil {
			s.resolveCancel()
			s.resolveCancel = nil
		}
		return result.err
	default:
		return nil
	}
}

func (s *HotState) WaitResolveAllPending(ctx context.Context) error {
	if s == nil || s.resolveDone == nil {
		return nil
	}
	select {
	case result := <-s.resolveDone:
		s.resolveInProgress = false
		s.resolveDone = nil
		if s.resolveCancel != nil {
			s.resolveCancel()
			s.resolveCancel = nil
		}
		return result.err
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (s *HotState) resolveAllParallel(ctx context.Context, conn *ch.Client, db string) error {
	type resolveJob struct {
		name    string
		resolve func(context.Context, *ch.Client, string) error
	}
	var jobs []resolveJob
	if s.ConditionsResolver.Pending() > 0 {
		jobs = append(jobs, resolveJob{
			name: "MemoryCondition",
			resolve: func(ctx context.Context, conn *ch.Client, db string) error {
				return s.ConditionsResolver.Resolve(ctx, conn, db)
			},
		})
	}
	if s.UserPositionsResolver.Pending() > 0 {
		jobs = append(jobs, resolveJob{
			name: "MemoryUserPosition",
			resolve: func(ctx context.Context, conn *ch.Client, db string) error {
				return s.UserPositionsResolver.Resolve(ctx, conn, db)
			},
		})
	}
	if s.MarketsResolver.Pending() > 0 {
		jobs = append(jobs, resolveJob{
			name: "MemoryMarket",
			resolve: func(ctx context.Context, conn *ch.Client, db string) error {
				return s.MarketsResolver.Resolve(ctx, conn, db)
			},
		})
	}
	if s.NegRiskEventsResolver.Pending() > 0 {
		jobs = append(jobs, resolveJob{
			name: "MemoryNegRiskEvent",
			resolve: func(ctx context.Context, conn *ch.Client, db string) error {
				return s.NegRiskEventsResolver.Resolve(ctx, conn, db)
			},
		})
	}
	if s.FixedProductMarketMakersResolver.Pending() > 0 {
		jobs = append(jobs, resolveJob{
			name: "MemoryFixedProductMarketMaker",
			resolve: func(ctx context.Context, conn *ch.Client, db string) error {
				return s.FixedProductMarketMakersResolver.Resolve(ctx, conn, db)
			},
		})
	}
	if len(jobs) == 0 {
		return nil
	}
	concurrency := asyncResolveConcurrency()
	if concurrency > len(jobs) {
		concurrency = len(jobs)
	}
	sem := make(chan struct{}, concurrency)
	var wg sync.WaitGroup
	errMu := sync.Mutex{}
	var firstErr error
	for _, job := range jobs {
		wg.Add(1)
		go func(j resolveJob) {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()
			if ctx.Err() != nil {
				return
			}
			if err := j.resolve(ctx, conn, db); err != nil {
				errMu.Lock()
				if firstErr == nil {
					firstErr = fmt.Errorf("%s resolve: %w", j.name, err)
				}
				errMu.Unlock()
			}
		}(job)
	}
	wg.Wait()
	return firstErr
}

