// commitBatches holds the column batches snapshotted from the dirty sets, ready to
// INSERT. It is self-contained (value copies only) and references NO hot-ring state,
// so insert() can run in a background goroutine concurrently with the fold without
// racing the ring (the async-commit path; see State.StartCommit).
type commitBatches struct {
	Conditions               *MemoryConditionBatch
	UserPositions            *MemoryUserPositionBatch
	Markets                  *MemoryMarketBatch
	NegRiskEvents            *MemoryNegRiskEventBatch
	FixedProductMarketMakers *MemoryFixedProductMarketMakerBatch
}

// snapshotDirty builds the insert batches from the dirty sets + hot ring and clears
// the dirty sets, under s.mu and with NO network I/O. It MUST be called from the
// single processor (consumer) goroutine: Get may promote a cold entry into the ring
// (a ring mutation), which is only safe when no other goroutine touches the ring. The
// returned batches hold value copies only, so the subsequent Insert is ring-free.
func (s *HotState) snapshotDirty() *commitBatches {
	s.mu.Lock()
	defer s.mu.Unlock()
	cb := &commitBatches{}
	if len(s.dirtyConditions) > 0 {
		cb.Conditions = NewMemoryConditionBatch()
		for key := range s.dirtyConditions {
			if val, ok := s.Conditions.Get(key); ok {
				cb.Conditions.Append(val)
			}
		}
		clear(s.dirtyConditions)
	}
	if len(s.dirtyUserPositions) > 0 {
		cb.UserPositions = NewMemoryUserPositionBatch()
		for key := range s.dirtyUserPositions {
			if val, ok := s.UserPositions.Get(key); ok {
				cb.UserPositions.Append(val)
			}
		}
		clear(s.dirtyUserPositions)
	}
	if len(s.dirtyMarkets) > 0 {
		cb.Markets = NewMemoryMarketBatch()
		for key := range s.dirtyMarkets {
			if val, ok := s.Markets.Get(key); ok {
				cb.Markets.Append(val)
			}
		}
		clear(s.dirtyMarkets)
	}
	if len(s.dirtyNegRiskEvents) > 0 {
		cb.NegRiskEvents = NewMemoryNegRiskEventBatch()
		for key := range s.dirtyNegRiskEvents {
			if val, ok := s.NegRiskEvents.Get(key); ok {
				cb.NegRiskEvents.Append(val)
			}
		}
		clear(s.dirtyNegRiskEvents)
	}
	if len(s.dirtyFixedProductMarketMakers) > 0 {
		cb.FixedProductMarketMakers = NewMemoryFixedProductMarketMakerBatch()
		for key := range s.dirtyFixedProductMarketMakers {
			if val, ok := s.FixedProductMarketMakers.Get(key); ok {
				cb.FixedProductMarketMakers.Append(val)
			}
		}
		clear(s.dirtyFixedProductMarketMakers)
	}
	return cb
}

// insert writes the snapshotted batches to ClickHouse. It touches NO hot-ring state,
// so it is safe to run in a background goroutine concurrently with the fold.
func (cb *commitBatches) insert(ctx context.Context, conn *ch.Client, db string) error {
	if cb.Conditions != nil {
		if err := cb.Conditions.Insert(ctx, conn, db); err != nil {
			return err
		}
	}
	if cb.UserPositions != nil {
		if err := cb.UserPositions.Insert(ctx, conn, db); err != nil {
			return err
		}
	}
	if cb.Markets != nil {
		if err := cb.Markets.Insert(ctx, conn, db); err != nil {
			return err
		}
	}
	if cb.NegRiskEvents != nil {
		if err := cb.NegRiskEvents.Insert(ctx, conn, db); err != nil {
			return err
		}
	}
	if cb.FixedProductMarketMakers != nil {
		if err := cb.FixedProductMarketMakers.Insert(ctx, conn, db); err != nil {
			return err
		}
	}
	if err := flushAsyncInserts(ctx, conn); err != nil {
		return err
	}
	return nil
}

// Commit synchronously snapshots the dirty sets and inserts them. The async path is
// State.StartCommit, which snapshots in the consumer thread and runs only insert() in
// a goroutine, so the network insert never holds s.mu or touches the ring.
func (s *HotState) Commit(ctx context.Context, conn *ch.Client, db string) error {
	if conn == nil {
		s.mu.Lock()
		clear(s.dirtyConditions)
		clear(s.dirtyUserPositions)
		clear(s.dirtyMarkets)
		clear(s.dirtyNegRiskEvents)
		clear(s.dirtyFixedProductMarketMakers)
		s.mu.Unlock()
		return nil
	}
	return s.snapshotDirty().insert(ctx, conn, db)
}
func (s *HotState) RestoreMemoryCondition(key ConditionsClockKey, value MemoryCondition, had bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if had {
		s.Conditions.SetByKey(key, value)
		s.dirtyConditions[key] = struct{}{}
		return
	}
	s.Conditions.Delete(key)
	delete(s.dirtyConditions, key)
}

